import os
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, redirect, session
import psycopg2
import yaml
import subprocess

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'webapp123')

def get_db():
    return psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)

@app.route('/api/users/search')
def user_search():
    """Search users with filters - uses parameterized queries"""
    name = request.args.get('name', '')
    role = request.args.get('role', 'user')
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email FROM users WHERE name ILIKE %s AND role = %s",
                (f'%{name}%', role))
    results = cur.fetchall()
    conn.close()
    return jsonify([{'id': r[0], 'username': r[1], 'email': r[2]} for r in results])

@app.route('/api/analytics/query', methods=['POST'])
def analytics_query():
    """Execute analytics query with user-specified dimensions"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    metric = data.get('metric', 'count')
    dimension = data.get('dimension', 'day')
    table = data.get('source', 'events')

    # Validate metric against allowed list
    allowed_metrics = ['count', 'sum', 'avg', 'min', 'max']
    if metric not in allowed_metrics:
        return jsonify({'error': 'Invalid metric'}), 400

    # Build query - dimension is used in GROUP BY
    conn = get_db()
    cur = conn.cursor()
    query = f"SELECT {dimension}, {metric}(value) FROM {table} GROUP BY {dimension} ORDER BY {dimension}"
    try:
        cur.execute(query)
        results = cur.fetchall()
    except Exception as e:
        conn.close()
        return jsonify({'error': str(e)}), 500
    conn.close()
    return jsonify({'data': results})

@app.route('/api/config/load', methods=['POST'])
def load_config():
    """Load YAML configuration"""
    raw = request.get_data(as_text=True)
    try:
        config = yaml.safe_load(raw)
    except yaml.YAMLError as e:
        return jsonify({'error': str(e)}), 400
    return jsonify({'status': 'loaded', 'keys': list(config.keys()) if config else []})

@app.route('/api/reports/schedule', methods=['POST'])
def schedule_report():
    """Schedule a report generation job"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    report_id = data.get('report_id', '')
    schedule = data.get('cron', '0 * * * *')
    notify_email = data.get('notify', '')

    # Write cron entry for report scheduler
    cron_line = f"{schedule} /usr/bin/python3 /app/generate_report.py --id={report_id} --notify={notify_email}\n"

    with open('/var/spool/cron/reports', 'a') as f:
        f.write(cron_line)

    return jsonify({'status': 'scheduled', 'report_id': report_id})

@app.route('/api/export/run', methods=['POST'])
def run_export():
    """Trigger data export to specified format"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    export_format = data.get('format', 'csv')
    dataset = data.get('dataset', 'default')

    # Sanitize dataset name
    if not dataset.isalnum():
        return jsonify({'error': 'Invalid dataset name'}), 400

    cmd = f"/app/bin/exporter --format {export_format} --dataset {dataset} --output /tmp/exports/"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)

    return jsonify({
        'status': 'completed' if result.returncode == 0 else 'failed',
        'output': result.stdout[:500]
    })

@app.route('/healthz')
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
